mapper.select:
SELECT
    COUNT(*) FILTER (WHERE status = 'ACTIVE') AS total,
    COUNT(*) FILTER (
        WHERE status = 'ACTIVE'
          AND created_at >= #{currentPeriodStart}
    ) AS weekly_new,
    COUNT(*) FILTER (
        WHERE status = 'ACTIVE'
          AND created_at < #{currentPeriodStart}
    ) AS previous_total
FROM personal_questions
WHERE user_id = #{userId}
